-- 0014_devices_mac_not_unique — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- D-29: a device is identified by its serial number. The MAC can change when a device restarts, so it is the
-- last value seen (from the device platform or an import), not an identity: two active devices may report the
-- same MAC. R6 now blocks only a duplicate SN; the SN index of 0007 stays.
DROP INDEX device_active_mac;
CREATE INDEX device_mac ON device (mac) WHERE mac IS NOT NULL;
COMMENT ON COLUMN device.mac IS 'Last MAC seen (D-29): not unique, can change on restart';
